LAYER
    NAME "wrf_daily_rainfall"
    TYPE RASTER
    STATUS ON
    DATA "/opt/cogs/wrf-daily-rainfall/%time%/wrf_daily_%time%.tif"
    MASK "gha_admin_extent_mask"
    PROCESSING "NODATA=0"
    PROJECTION
        "init=epsg:4326"
    END
    INCLUDE "classifications/wrf-rainfall-raster.classes.map"
    METADATA
        "wms_title" "WRF Daily Rainfall"
        "wms_abstract" "Daily rainfall forecast from WRF model (mm), served from COG"
        INCLUDE "shared/wms-layer-metadata.map"
    END
    VALIDATION
        "time" "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
        "default_time" "2026-03-31"
    END
END
